// Knowledge base: product FAQ chunks (the "documents" to search over)
return [
  { json: { text: "Our business hours are Monday to Friday, 9 AM to 6 PM Eastern Time. We are closed on weekends and major public holidays. Urgent issues on paid enterprise plans get 24/7 support.", metadata: { category: "hours", id: 1 } } },
  { json: { text: "To reset your password, click 'Forgot Password' on the login page and follow the email link. The reset link expires after 30 minutes. If you don't get the email, check your spam folder or contact support@acme.com.", metadata: { category: "account", id: 2 } } },
  { json: { text: "We offer three plans: Starter ($19/mo, 1 user), Pro ($49/mo, up to 10 users), and Enterprise (custom pricing, unlimited users plus SSO). Annual billing gives 2 months free.", metadata: { category: "pricing", id: 3 } } },
  { json: { text: "Our refund policy allows a full refund within 14 days of purchase for annual plans. Monthly plans are non-refundable but you can cancel anytime to stop future charges.", metadata: { category: "billing", id: 4 } } },
  { json: { text: "You can export your data anytime from Settings > Data > Export. We support CSV and JSON formats. Enterprise plans also get scheduled exports to S3 or BigQuery.", metadata: { category: "data", id: 5 } } }
];

// Semantic-style retrieval: score every chunk against the question
// (token overlap + bigram boost) and return the best match.
const question = $('Set Question').item.json.question.toLowerCase();
const stop = new Set(['the','a','an','is','are','do','does','how','what','when','where','i','my','to','of','in','on','for','can','you','we','it','and','or']);
const qTokens = question.replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(t => t && !stop.has(t));
const chunks = $('FAQ Chunks').all().map(i => i.json);
let best = null, bestScore = -1;
for (const c of chunks) {
  const text = (c.text || '').toLowerCase();
  let score = 0;
  for (const t of qTokens) if (text.includes(t)) score += 1;
  for (let i = 0; i < qTokens.length - 1; i++)
    if (text.includes(qTokens[i] + ' ' + qTokens[i+1])) score += 2;
  if (score > bestScore) { bestScore = score; best = c; }
}
return [{ json: { text: best.text, metadata: best.metadata, matchScore: bestScore } }];

