parameters.jsCode:
const item = $input.first().json;
let raw = '';
if (item.text) { raw = item.text; }
else if (item.content && Array.isArray(item.content.parts)) {
  raw = item.content.parts.filter(p => !p.thought).map(p => p.text || '').join('');
}
const question = $('Set Question').item.json.question;
const retrieved = $('Retrieve Best Chunk').first().json;
return [{ json: {
  Timestamp: new Date().toISOString(),
  Question: question,
  Answer: (raw || '').trim(),
  Source: retrieved.metadata ? retrieved.metadata.category : 'faq-chunk',
  MatchScore: retrieved.matchScore
}}];
